import pandas as pd


def _get_input(inputs: dict, *names):
    for n in names:
        if n in inputs:
            return inputs[n]
    # case-insensitive fallback
    lower_map = {k.lower(): k for k in inputs.keys()}
    for n in names:
        if n.lower() in lower_map:
            return inputs[lower_map[n.lower()]]
    raise KeyError(f"None of {names} found in inputs keys {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim_df = _get_input(inputs, 'DIM_ACCOUNT', 'dim_account').copy()
    stg_df = _get_input(inputs, 'STG_ACCOUNT', 'stg_account').copy()

    # Normalize date columns to pandas Timestamps for safe comparisons.
    dim_df['eff_start_date'] = pd.to_datetime(dim_df['eff_start_date'])
    dim_df['eff_end_date'] = pd.to_datetime(dim_df['eff_end_date'])
    stg_df['update_date'] = pd.to_datetime(stg_df['update_date'])

    # Build per-account list of current versions from DIM_ACCOUNT.
    versions = {}
    for acc_id, group in dim_df.groupby('account_id'):
        vlist = []
        for _, row in group.iterrows():
            vlist.append({
                'plan': row['plan'],
                'eff_start_date': row['eff_start_date'],
                'eff_end_date': row['eff_end_date'],
                'is_current': row['is_current'],
            })
        versions[acc_id] = vlist

    def plans_equal(p1, p2):
        n1 = pd.isna(p1)
        n2 = pd.isna(p2)
        if n1 and n2:
            return True
        if n1 or n2:
            return False
        return p1 == p2

    # Cursor order: account_id, update_date ASC (stable for ties, though
    # (account_id, update_date) is guaranteed unique in staging).
    stg_sorted = stg_df.sort_values(['account_id', 'update_date'], kind='mergesort')

    for _, s in stg_sorted.iterrows():
        acc_id = s['account_id']
        plan = s['plan']
        d = s['update_date']

        if acc_id not in versions or len(versions[acc_id]) == 0:
            versions[acc_id] = [{
                'plan': plan,
                'eff_start_date': d,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            }]
            continue

        vlist = versions[acc_id]

        # Find the version covering date d: start <= d < end (end NULL = open).
        v = None
        for ver in vlist:
            start_ok = ver['eff_start_date'] <= d
            end_ok = pd.isna(ver['eff_end_date']) or d < ver['eff_end_date']
            if start_ok and end_ok:
                v = ver
                break

        if v is None:
            # update_date earlier than the account's earliest version.
            f = min(vlist, key=lambda x: x['eff_start_date'])
            vlist.append({
                'plan': plan,
                'eff_start_date': d,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            })
        elif plans_equal(v['plan'], plan):
            # no-op
            pass
        elif d == v['eff_start_date']:
            # same-day correction, no new version
            v['plan'] = plan
        else:
            # split v at d
            vlist.append({
                'plan': plan,
                'eff_start_date': d,
                'eff_end_date': v['eff_end_date'],
                'is_current': v['is_current'],
            })
            v['eff_end_date'] = d
            v['is_current'] = 0

    # Flatten result.
    rows = []
    for acc_id, vlist in versions.items():
        for ver in vlist:
            rows.append({
                'account_id': acc_id,
                'plan': ver['plan'],
                'eff_start_date': ver['eff_start_date'],
                'eff_end_date': ver['eff_end_date'],
                'is_current': ver['is_current'],
            })

    out = pd.DataFrame(
        rows,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current']
    )

    if not out.empty:
        out['is_current'] = out['is_current'].astype(int)
        out = out.sort_values(
            ['account_id', 'eff_start_date'], kind='mergesort'
        ).reset_index(drop=True)

    return {'dim_account_out': out}
